public class ShadowEngine 
{
	private World World;

	public int[][] Tiles;
	public int[][] Shadows;
	public int[][] BackdropShadows;
	public int[][] FakeBackdropShadows;

	private List<LightPoint> LightPoints;

	@SuppressWarnings("unused")
	private GuiPlay Play;

	private Mask[][][] Masks;

    public ShadowEngine(World World, GuiPlay Play)
    {
    	this.World = World;

    	Tiles = World.getWorldProvider().getTiles();
    	Shadows = new int[World.getWorldProvider().getWidth()][World.getWorldProvider().getHeight()];
    	BackdropShadows = new int[World.getWorldProvider().getWidth()][World.getWorldProvider().getHeight()];
    	FakeBackdropShadows = new int[World.getWorldProvider().getWidth()][World.getWorldProvider().getHeight()];

    	LightPoints = new CopyOnWriteArrayList<LightPoint>();

    	this.Play = Play;

    	LightPoints.add(new LightPoint(20, 30, 1, 1, 1));

    	Masks = new Mask[16][16][18];

    	for(int I = 0; I < 16; I++)
    	{
    		for(int J = 0; J < 16; J++)
    		{
    			for(int K = 0; K < 15; K++)
    			{
    				try 
    				{
						Masks[I][J][getShadowi(K)] = new Mask(getShadow(getShadowi(K)).getData(), LightPointSprites.LightPointSprite[I][J], 1);
					} 
    				catch (IOException e) 
    				{
						e.printStackTrace();
					}
    			}
    		}
    	}
    }

